-- Expanded Ready SETCO Skills & Work starter courses.
-- Update only the original unedited drafts. Published versions and officer edits are preserved.

UPDATE learning_course_versions SET
  description='Draft a checklist with AI and check it against a reliable human or written source.',
  lessons_json=json_array(
    json('{"title":"Make the request specific","body":"Choose a low-risk task such as making a fictional event checklist clearer. Describe the audience, job and output. Use fictional details and leave out private names, sensitive instructions and records.","captureNotes":"Record an example in a chosen tool using made-up inputs. Show the prompt and draft as separate items. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Which prompt gives enough detail for a low-risk checklist draft?","choices":[{"id":"a","text":"Paste a real contact list and ask for a useful plan of any kind."},{"id":"b","text":"State the audience, task, fictional context, desired output and any limits."},{"id":"c","text":"Ask it to guess the latest venue procedures and skip reviewing the answer."}],"correct_choice_id":"b","explanation":"Specific fictional inputs help the model draft something the user can check.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An AI answer includes a private operational detail from your input. What should you do before sharing?","choices":[{"id":"a","text":"Share it internally first and ask if anyone recognises the detail."},{"id":"b","text":"Leave it in because the model returned it unchanged."},{"id":"c","text":"Remove it, adjust the inputs and use only details approved for the audience."}],"correct_choice_id":"c","explanation":"The author controls what information goes into the shared output.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Check every instruction before using it","body":"Compare the answer with the real, authorised process. Remove guesses, confirm names or facts with the source and ask the responsible person to review it. Keep the useful prompt and the corrected version together.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The model produces a clear checklist that disagrees with the official process. What should happen?","choices":[{"id":"a","text":"Follow the authorised source, correct the draft and ask the responsible person to review it."},{"id":"b","text":"Prefer the model wording because most learners find it clear."},{"id":"c","text":"Add both versions and let the learner decide what applies."}],"correct_choice_id":"a","explanation":"Clarity is valuable and the agreed operating process still governs.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An AI draft invents a venue rule. What should you do?","choices":[{"id":"a","text":"Keep it because it sounds plausible"},{"id":"b","text":"Check the actual venue source and correct or remove it"}],"correct_choice_id":"b","explanation":"The venue rules need a source that has authority.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Choose a suitable task and protect inputs","body":"Decide whether the intended use is agreed and what a human needs to check. Choose a bounded draft with a source the team can verify. Use fictional or approved material and exclude private client, personnel and restricted cultural data. Check where the tool may process and retain information under the actual workplace process.\n\nKeep the agreed task and input limits, source and review owner in the authorised record.","captureNotes":"Walk through Ready SETCO learning and workplace procedure with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the agreed task and input limits, source and review owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A real member list would make a reminder draft more realistic. What should you use?","choices":[{"id":"a","text":"Paste the real list because the output will be checked before sending."},{"id":"b","text":"Use invented details or the minimum input explicitly approved for that system and use."}],"correct_choice_id":"b","explanation":"The operating record needs the agreed task and input limits, source and review owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the agreed task and input limits, source and review owner"},{"id":"b","text":"a saved prompt with real member details for convenient reuse"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Write and test a clear prompt","body":"State the task, audience, source and expected shape. Specify assumptions to leave open and ask the tool to mark what it cannot verify. Test one sample against the actual process. Vary a condition to see whether the output still respects the important constraints. Record which prompt and source version produced the output.\n\nKeep the prompt, source, tested examples and unresolved claims in the authorised record.","captureNotes":"Walk through Course builder AI draft and source material with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the prompt, source, tested examples and unresolved claims using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The draft correctly describes normal work but makes up a step for an exception. What do you do?","choices":[{"id":"a","text":"Compare the exception against the approved source and revise or escalate before reuse."},{"id":"b","text":"Accept it because the usual situation was described correctly."}],"correct_choice_id":"a","explanation":"The operating record needs the prompt, source, tested examples and unresolved claims. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a strong-looking example with no source or exception test"},{"id":"b","text":"the prompt, source, tested examples and unresolved claims"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Review sensitive or consequential output","body":"Check decision-relevant facts and current instructions against their authorised source. Use qualified or responsible staff for finance, safety, permissions and employment decisions. Ask whose sign-off is needed and record corrections. Do not treat model confidence or a polished result as confirmation. Recheck names, tone, accessibility and confidential details before release.\n\nKeep the corrected source and named review, with any unresolved safety or permission matter in the authorised record.","captureNotes":"Walk through Workplace review and approval with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the corrected source and named review, with any unresolved safety or permission matter using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A checklist includes a plausible safety instruction that differs from the current site procedure. Which is actionable?","choices":[{"id":"a","text":"Retain the model’s language as a second option for new staff."},{"id":"b","text":"Use the verified site process and have the responsible person review the corrected wording."}],"correct_choice_id":"b","explanation":"The operating record needs the corrected source and named review, with any unresolved safety or permission matter. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the corrected source and named review, with any unresolved safety or permission matter"},{"id":"b","text":"a preferred draft chosen solely for readability"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Hand over the result and recognise when to stop","body":"Record the verified final version, responsible person, source date and what you corrected. Keep private or unsafe information out of the shared prompt. Identify an escalation for disputed content, a wrong release or a provider change and ask the team to confirm any later revision. Keep it possible for someone else to repeat the checks.\n\nKeep the corrected output, release destinations, responsible review and next check in the authorised record.","captureNotes":"Walk through Checked version and feedback log with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the corrected output, release destinations, responsible review and next check using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A supervisor spots an error after the checklist was shared. What should happen?","choices":[{"id":"a","text":"Verify impact, correct or remove the affected version through the owner and tell the people who rely on it."},{"id":"b","text":"Quietly edit the copy and leave previously distributed versions alone."}],"correct_choice_id":"a","explanation":"The operating record needs the corrected output, release destinations, responsible review and next check. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a revised prompt with no account of the released version"},{"id":"b","text":"the corrected output, release destinations, responsible review and next check"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Use a fictional job task. Submit your scoped prompt, intended inputs and exclusions, an example output, source checks including one exception, the corrected version and its review and release record. Include a plan to correct or withdraw the output if it is wrong. Pass when the assessor can repeat your checks and all consequential instructions are supported or held for the responsible person.',
  edit_version=edit_version+1
WHERE course_id='training-ai-work-skills' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Prepare an officer to handle rules and authority, meeting and decision records, finance oversight, private information, delivery risks and a verifiable handover.',
  lessons_json=json_array(
    json('{"title":"Identify the organisation and governing authority","body":"Check whether you are acting for an existing entity, an operator, or a proposed group. Find the current rules, appointed officers, delegated decisions and obligations. Explain which decisions a team can make and when a member decision or another organisation’s acceptance is needed. Use the Ready SETCO formation guide for preparation and check the actual regulator, rules and adviser relevant to the organisation.\n\nKeep the organisation status, current rules, authority and decision responsibilities in the authorised record.","captureNotes":"Walk through Formation and governance with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the organisation status, current rules, authority and decision responsibilities using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A planning tool says someone is Chair before the required appointment has happened. What can you rely on?","choices":[{"id":"a","text":"An actual authority record and current rules, with any appointment still pending shown honestly."},{"id":"b","text":"The title in the planning tool because it assigns oversight."}],"correct_choice_id":"a","explanation":"The operating record needs the organisation status, current rules, authority and decision responsibilities. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a planning account and title with no appointment record"},{"id":"b","text":"the organisation status, current rules, authority and decision responsibilities"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Prepare a meeting ready to decide","body":"Confirm notice, purpose, time, eligible people, quorum arrangement and how the agenda is accepted under the applicable rules. Include papers, the decision needed and who can present it. Check financial, site or membership evidence and use the right meeting for the decision. Flag late items and source gaps and ask the Secretary or Chair to confirm what can proceed.\n\nKeep the notice, agenda, eligibility, evidence, decision status and owner in the authorised record.","captureNotes":"Walk through Meetings and decisions with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the notice, agenda, eligibility, evidence, decision status and owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A decision is added late and attendees have not seen supporting papers. What should be verified?","choices":[{"id":"a","text":"Proceed if a majority say they can decide without the papers."},{"id":"b","text":"Check timing, notice and whether the decision needs deferral or a different meeting."}],"correct_choice_id":"b","explanation":"The operating record needs the notice, agenda, eligibility, evidence, decision status and owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the notice, agenda, eligibility, evidence, decision status and owner"},{"id":"b","text":"an agenda title and informal agreement with no rule check"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Record interests, outcomes and responsibility","body":"Obtain required disclosures and record how they were handled. Check quorum and voting under the organisation’s rules. Record the actual motion, wording, timing, outcome and named actions. Check approved minutes against draft notes and share only the intended edition. Track amendments, follow-through and open issues against the same source record, retaining restricted evidence in its proper location.\n\nKeep the source decision, disclosure handling, actual vote or deferral and action follow-up in the authorised record.","captureNotes":"Walk through Decision register with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the source decision, disclosure handling, actual vote or deferral and action follow-up using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An interested person leaves and quorum becomes uncertain. What do you record?","choices":[{"id":"a","text":"Record the disclosure and quorum issue and defer the affected decision if it cannot proceed."},{"id":"b","text":"Record a decision based on people who remain, then ask others to endorse it by message."}],"correct_choice_id":"a","explanation":"The operating record needs the source decision, disclosure handling, actual vote or deferral and action follow-up. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"an undated summary including presumed agreement"},{"id":"b","text":"the source decision, disclosure handling, actual vote or deferral and action follow-up"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Oversee money, grants and delegated or partner work","body":"Ask for approved amounts, restricted funds, who can authorise each expense or agreement, and what proof is required. For a proposed partner ask who owns the work, which responsibilities stay with the original operator, exact written acceptance, review date and status. Keep approved evidence, forecasts and offers distinguishable. Check filing and reporting obligations with the responsible officer and competent source.\n\nKeep the verified scope, funding and responsibilities with conditions, authority and dates in the authorised record.","captureNotes":"Walk through Finance and service handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the verified scope, funding and responsibilities with conditions, authority and dates using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A draft budget includes funding and a partner mentioned in an enquiry. What should the decision record say?","choices":[{"id":"a","text":"Treat them as confirmed in the latest plan because they were discussed with the group."},{"id":"b","text":"Show both as pending until confirmed, name the verifying owners and note retained responsibilities."}],"correct_choice_id":"b","explanation":"The operating record needs the verified scope, funding and responsibilities with conditions, authority and dates. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the verified scope, funding and responsibilities with conditions, authority and dates"},{"id":"b","text":"a plan total and names with no acceptance evidence"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Handle records, complaints and safe participation","body":"Agree record ownership, access, retention and how people can request corrections. Separate a public summary, member copy and restricted working record. Refer complaints, youth safety, privacy or serious incidents to the appropriate process and decision-maker promptly. Record what the authorised person needs without circulating unnecessary details. For an event, check venue, crew and responsibility for changing or stopping delivery.\n\nKeep the restricted case reference, actual plan and approved owner for each next action in the authorised record.","captureNotes":"Walk through Club support and member records with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the restricted case reference, actual plan and approved owner for each next action using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A concern arrives as a private attachment and relates to a public event. What should go on the officer list?","choices":[{"id":"a","text":"A minimal action reference and authorised contact, keeping sensitive evidence in the controlled location."},{"id":"b","text":"The full attachment because the public event involves many officers."}],"correct_choice_id":"a","explanation":"The operating record needs the restricted case reference, actual plan and approved owner for each next action. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"an open copy of private evidence in the general minutes"},{"id":"b","text":"the restricted case reference, actual plan and approved owner for each next action"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Operate the cycle and hand over","body":"Keep a current list of meetings, formal returns where relevant, reports, event changes, renewals, supporting records and obligations. At transition, verify access for incoming and outgoing colleagues, custody of property, revised authority and actual acceptance by others. Walk the successor through live tasks, disagreements and privacy limits and agree a first-week review and open deadlines. Use a dated source for each task.\n\nKeep the dated roles, records, access checks and concrete open tasks in the authorised record.","captureNotes":"Walk through Formation planner and Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the dated roles, records, access checks and concrete open tasks using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"All accounts work but a pending filing and decision cannot be found. Does handover close?","choices":[{"id":"a","text":"Close since access works and the successor can start a new record."},{"id":"b","text":"Keep the source and filing checks open with owners and dates, and verify them at the next check-in."}],"correct_choice_id":"b","explanation":"The operating record needs the dated roles, records, access checks and concrete open tasks. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the dated roles, records, access checks and concrete open tasks"},{"id":"b","text":"an access checklist with no obligations or outstanding decisions"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Choose a fictional club or cooperative planning group. Submit an authority and roles map, committee and member decision example, notice and minutes, an interest or quorum exception, a financial or partner decision with checks, and a restricted concern handoff. Give the next officer a dated records and access handover with owners. Pass when the status and governing source are correctly identified, every action is traceable to its authority and private material is kept in the right route.',
  edit_version=edit_version+1
WHERE course_id='training-committee-basics' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Build a short run sheet and rehearse a change to a local event.',
  lessons_json=json_array(
    json('{"title":"Give each job an owner","body":"Confirm the venue, expected audience, lead roles and time checks. Include accessible arrival, a contact for concerns, permission checks and the decision point for changing the schedule.","captureNotes":"Record a fictional event run sheet and point out the owner, due time and backup in each row. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An event has one person allocated to two jobs at doors open. How do you fix the run sheet?","choices":[{"id":"a","text":"Shorten both job labels so the person can complete them faster."},{"id":"b","text":"Wait until doors open to ask whoever is free to handle one."},{"id":"c","text":"Give each simultaneous job time, an owner and a backup as needed."}],"correct_choice_id":"c","explanation":"A live plan has to account for roles needing attention at the same time.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two arrival paths are shown and one may be inaccessible. What do you include?","choices":[{"id":"a","text":"The confirmed accessible route and the person checking any uncertainty."},{"id":"b","text":"The shortest path only because it is simpler to publicise."},{"id":"c","text":"Both directions without specifying which needs checking."}],"correct_choice_id":"a","explanation":"The audience needs workable arrival details and a contact.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Rehearse the handover","body":"Practise a late venue change with the crew. Ask the authorised person to confirm the public wording and updated channels. At close, check the equipment and record any issue for the next team.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A text message circulates a different venue after a change. What should the lead do?","choices":[{"id":"a","text":"Send another version privately without updating the public notice."},{"id":"b","text":"Confirm the current source and share one agreed update through the chosen channels."},{"id":"c","text":"Wait until people arrive to explain the two options."}],"correct_choice_id":"b","explanation":"A coordinated message sets out the verified change and where it applies.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What should a crew handover contain after a change?","choices":[{"id":"a","text":"Just the name of the event"},{"id":"b","text":"The agreed update, source, people responsible and what still needs doing"}],"correct_choice_id":"b","explanation":"The next team needs instructions and open actions they can verify.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Scope the event and confirm roles","body":"Name the actual organiser, purpose, site, time, audience capacity, accessibility, required approvals and coverage. Allocate setup, welcome, safety, equipment and closing, including backup for gaps. Check whether any duties are paid or voluntary and what induction and checks apply. Confirm who signs off readiness and affects venue or budgets.\n\nKeep the venue and activity permissions, names of leads and open roles or conditions in the authorised record.","captureNotes":"Walk through Events and run sheet with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the venue and activity permissions, names of leads and open roles or conditions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The roster is filled but the venue’s agreed capacity or use is missing. What does the lead record?","choices":[{"id":"a","text":"A completed event plan because all crew members are assigned."},{"id":"b","text":"A venue dependency and named authority to confirm it before declaring ready."}],"correct_choice_id":"b","explanation":"The operating record needs the venue and activity permissions, names of leads and open roles or conditions. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the venue and activity permissions, names of leads and open roles or conditions"},{"id":"b","text":"a roster treated as full event approval"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Brief for risks and changing conditions","body":"Walk through agreed access and exit routes, equipment, vulnerable participants, weather or other triggers, welfare and first response. Refer specialist decisions to the responsible person and fit the private escalation to the role. Set the go, pause and stop contacts and verified public channel. Rehearse a change and ask crew to say how they would confirm it.\n\nKeep the actual triggers, who decides and where crew and public will hear the change in the authorised record.","captureNotes":"Walk through Crew briefing and event lead with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the actual triggers, who decides and where crew and public will hear the change using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A crowd or weather change exceeds the briefing conditions. What should the crew do?","choices":[{"id":"a","text":"Follow the pause or stop process and have the responsible lead issue one verified update."},{"id":"b","text":"Assume each volunteer can set new conditions for their own part of the event."}],"correct_choice_id":"a","explanation":"The operating record needs the actual triggers, who decides and where crew and public will hear the change. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a general warning to use caution with no role"},{"id":"b","text":"the actual triggers, who decides and where crew and public will hear the change"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Coordinate work, payments and authorised changes","body":"Update the versioned run sheet when scope, roster or equipment changes. Recheck that roles and permissions still fit. Handle gear, cash or expenses only through the authorised owners, count or log custody, and pass discrepancies and injuries or concerns to the designated route. Verify any changed audience message and keep detailed reports within the right audience.\n\nKeep the source change, current roles, evidence and who authorises any cost or duty in the authorised record.","captureNotes":"Walk through Run sheet, equipment and expense controls with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the source change, current roles, evidence and who authorises any cost or duty using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A new vendor change adds an unapproved fee during an event. What happens?","choices":[{"id":"a","text":"Pay it from the float and add it to the budget at close."},{"id":"b","text":"Check the authority and conditions and record a pending or approved change with its owner."}],"correct_choice_id":"b","explanation":"The operating record needs the source change, current roles, evidence and who authorises any cost or duty. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the source change, current roles, evidence and who authorises any cost or duty"},{"id":"b","text":"a changed run sheet with no acknowledgement or approval"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Close out, debrief and hand over","body":"Check attendance or results appropriate to the event, asset return, incidents, unresolved costs and actual messages. Keep agreed records and approve which feedback or photos may be shared. Assign every open action and hand the next team the current run sheet, unresolved issues and where to verify the source.\n\nKeep a verified close-out with open costs or faults, permissions and next owners in the authorised record.","captureNotes":"Walk through Event debrief and asset record with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include a verified close-out with open costs or faults, permissions and next owners using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The event finished but several loaned items have not been checked back in. What should the lead do?","choices":[{"id":"a","text":"Record custody and open follow-up per item, with responsible people and review time."},{"id":"b","text":"Close the event and let the equipment owner send a list later."}],"correct_choice_id":"a","explanation":"The operating record needs a verified close-out with open costs or faults, permissions and next owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a finished date and generic comments about what went well"},{"id":"b","text":"a verified close-out with open costs or faults, permissions and next owners"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Create a fictional event run sheet. Include access, venue and crew responsibilities, equipment or cash custody, safeguarding and emergency escalation contacts, one realistic change with the decision and corrected channels, and a debrief with asset and cost exceptions. Pass when the event lead can trace every critical check and change, including what to do if an approval or role is missing.',
  edit_version=edit_version+1
WHERE course_id='training-crew' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Practise care with map entries, local research sources and decisions about what may be shared.',
  lessons_json=json_array(
    json('{"title":"Record a useful observation","body":"Choose a fictional public place. Record what you saw, when, how to check it and what people need to know. Explain where a map pin or photograph came from and the audience it suits.","captureNotes":"Use a fictional map entry and the Ready SETCO public map or Cultural Intelligence Node reference material. Do not submit a live example. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A map pin came from a contributed photo without an exact location. How should it be recorded?","choices":[{"id":"a","text":"Record the source and uncertainty and check the place before publishing a precise pin."},{"id":"b","text":"Infer the position from a similar-looking place and mark it confirmed."},{"id":"c","text":"Choose a central location because the photo is genuine."}],"correct_choice_id":"a","explanation":"A genuine observation does not automatically establish a precise point.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two neighbours report different opening times for a public place. What do you do?","choices":[{"id":"a","text":"Replace both with the longer hours to make the map more useful."},{"id":"b","text":"Keep their observations distinct and check the current source before updating."},{"id":"c","text":"Treat the later report as definitive without noting its source."}],"correct_choice_id":"b","explanation":"Corrections should retain provenance and a reason for the public update.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Keep ownership and limits with the record","body":"Before sharing locations, personal details or cultural knowledge, ask who has authority and which audience and uses they approve. Preserve corrections and contact the custodian if the approved scope changes.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A custodian clears an observation for a small workshop but it appears in a draft map. What is appropriate?","choices":[{"id":"a","text":"Remove the name and publish because the record is useful."},{"id":"b","text":"Publish it briefly while checking whether anyone objects."},{"id":"c","text":"Keep it within its approved workshop use and ask about the proposed public use."}],"correct_choice_id":"c","explanation":"Changing the audience needs a separate scope decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A source supplies a location with restricted access. What should you do?","choices":[{"id":"a","text":"Record the restriction and confirm any intended use with the authorised custodian"},{"id":"b","text":"Copy it into a public map so people can verify it"}],"correct_choice_id":"a","explanation":"Anyone handling the record needs the same use instructions.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Agree scope and what can be recorded","body":"Describe the purpose, intended audience, data item, source and any sensitive location or community information. Ask who can authorise future use, including relevant cultural custodians. Decide where to record observation, consent and verification. Keep proposed interpretations separate from agreed facts and respect access limits.\n\nKeep source, status, restrictions, custodian and intended purpose in the authorised record.","captureNotes":"Walk through Map and place research with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include source, status, restrictions, custodian and intended purpose using invented details. Confirm the relevant custodian’s directions and privacy obligations for the actual organisation.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A field note identifies a place with restricted or culturally sensitive access. What is the first decision?","choices":[{"id":"a","text":"Check the scope with the appropriate custodians and keep recording or sharing within the permitted limits."},{"id":"b","text":"Map a less precise point and publish it while permission is being discussed."}],"correct_choice_id":"a","explanation":"The operating record needs source, status, restrictions, custodian and intended purpose. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a public pin that infers authority from its approximate location"},{"id":"b","text":"source, status, restrictions, custodian and intended purpose"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Collect accurate evidence and preserve provenance","body":"Record what you observed, date, method, uncertainty and how someone can verify it. Separate your own material and external links, check source and reuse permission and use only the information needed. Set a review date if conditions could change and preserve original notes in controlled custody.\n\nKeep the observation, actual source and uncertainty, check date and rights in the authorised record.","captureNotes":"Walk through Place observation and sources register with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the observation, actual source and uncertainty, check date and rights using invented details. Confirm the relevant custodian’s directions and privacy obligations for the actual organisation.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A precise map point was guessed from a publicly shared image. How should it be recorded?","choices":[{"id":"a","text":"Treat the point as exact because the image is already public."},{"id":"b","text":"Describe the source and uncertainty and verify the location before using a precise public point."}],"correct_choice_id":"b","explanation":"The operating record needs the observation, actual source and uncertainty, check date and rights. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the observation, actual source and uncertainty, check date and rights"},{"id":"b","text":"coordinates without a documented method or reliability"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Review before sharing and handle corrections","body":"Check the audience, location visibility, personal details, approved purpose and current facts before proposing an update. Choose the authorised review route and record old and new values, source and decision. When a report is unverified, label it and seek the responsible source. Observe withdrawal or restriction changes and verify the public outcome.\n\nKeep the review, permitted public change and any restricted evidence reference in the authorised record.","captureNotes":"Walk through Map suggestions and approval with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the review, permitted public change and any restricted evidence reference using invented details. Confirm the relevant custodian’s directions and privacy obligations for the actual organisation.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A proposed correction includes private notes that the reviewer should see. What do you submit where?","choices":[{"id":"a","text":"Pass protected evidence through the authorised route and keep the public change limited to approved details."},{"id":"b","text":"Publish the private note as support for the correction, then remove it later."}],"correct_choice_id":"a","explanation":"The operating record needs the review, permitted public change and any restricted evidence reference. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a public correction with no original source or record of authority"},{"id":"b","text":"the review, permitted public change and any restricted evidence reference"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Transfer custody and future decisions","body":"Prepare an index of source records, approved copies, date reviewed, access limits, responsible custodians and open questions. Acknowledge any restrictions on copying, publication or use by a new audience. Ask the incoming person to verify access and show how they would handle a correction, expiry or withdrawal with the appropriate authority.\n\nKeep the approved transfer, source, restrictions, current public version and named review in the authorised record.","captureNotes":"Walk through Place records handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the approved transfer, source, restrictions, current public version and named review using invented details. Confirm the relevant custodian’s directions and privacy obligations for the actual organisation.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A new team wants to reuse the record for a wider audience. What should be checked before transfer or release?","choices":[{"id":"a","text":"Treat permission to store the record as permission to publish it more widely."},{"id":"b","text":"The original scope and custodian’s decision on wider use, with the current approved version and restrictions."}],"correct_choice_id":"b","explanation":"The operating record needs the approved transfer, source, restrictions, current public version and named review. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the approved transfer, source, restrictions, current public version and named review"},{"id":"b","text":"an export of source and public content without any use limits"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Prepare a fictional observation and correction pack. Include provenance and uncertainty, scope and custodians or authorities, a public versus restricted version, a review record and a change or withdrawal test. Pass when the receiving person can verify the observation, what may be published, where restricted material belongs and who owns future corrections or reuse decisions.',
  edit_version=edit_version+1
WHERE course_id='training-digital-stewardship' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Prepare a contribution to the cooperative’s first decisions and identify what needs an agreement.',
  lessons_json=json_array(
    json('{"title":"Bring one need and one offer","body":"Name a local employment, training or resource need. Describe what the business might contribute and what conditions it would need. Use the declared formation status when speaking to staff or other businesses.","captureNotes":"Capture the public participation and formation pages with a fictional local employer. Reference site: https://ready-setco.auraofintelligence.workers.dev/"}'),
    json('{"title":"Move from discussion to an accountable decision","body":"Separate a founding idea from an approved contribution or recruitment arrangement. Identify who can authorise each commitment and who keeps the record. Discuss which responsibilities the business would retain."}'),
    json('{"title":"Distinguish offers and commitments","body":"Decide what the business could offer and what scope, costs or conditions would need approval. Confirm who speaks for the business and who keeps the record. Bring questions about membership, voting, role and services to the formation process rather than treating an enquiry as an agreement.","captureNotes":"Walk through Formation and participation with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}'),
    json('{"title":"Discuss work, supervision and resources","body":"Explain the real staffing or training need, possible available support, whether activity is paid or voluntary, and who would hire, supervise, equip and insure it. Ask what agreement, safety arrangements or evidence would apply. Confirm what capacity you actually have before promising delivery.","captureNotes":"Walk through Training and work and club support with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}'),
    json('{"title":"Agree decisions, privacy and follow-up","body":"Keep staff, candidate or customer information in the appropriate private process. Ask how your proposal and any eventual decision will be recorded and what conditions remain. Take back the scope, anticipated contribution, responsible people and review date for a business decision.","captureNotes":"Walk through Members and governance with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='training-employer-founding' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Prepare the questions and evidence for a future employer membership or service enquiry.',
  lessons_json=json_array(
    json('{"title":"Compare the type of participation","body":"Ask whether you are exploring membership, sharing a resource, offering jobs or buying a service. Check the status and applicable terms when that route exists. Identify who can speak for the business.","captureNotes":"Use the public membership page and an example employer enquiry. Reference site: https://ready-setco.auraofintelligence.workers.dev/"}'),
    json('{"title":"Confirm what the business would actually do","body":"Document responsibilities, timing, costs, information handling and who makes hiring and supervision decisions. If arranging introductions, confirm the role and what the person has agreed may be shared through the authorised process."}'),
    json('{"title":"Check which route you are exploring","body":"Compare membership, shared resources, local employment or contracting enquiries based on the actual available terms. Check the cooperative or operator status and the person with authority on both sides. Ask what responsibilities, costs, notice or changes would follow any eventual agreement.","captureNotes":"Walk through Member information and business participation with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}'),
    json('{"title":"Set up a responsible role or service","body":"Confirm if the business would be an employer, service partner, venue host or supporter. Discuss actual work, required qualifications or training, supervision, pay, safety, complaints and which records stay with each party. Check the appropriate permissions before requesting anyone else’s records.","captureNotes":"Walk through Training and work and support with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}'),
    json('{"title":"Record approval, access and ongoing review","body":"Keep the business’s authorised decision, accepted terms, condition for any contact introduction and who follows up on questions or changes. Use appropriate private referral and verification choices. Recheck the agreement before assigning work or sharing information for a different purpose.","captureNotes":"Walk through Membership and service follow-up with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='training-employer-onboarding' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Track commitments, approvals, receipts and outcomes from the first day of a fictional project.',
  lessons_json=json_array(
    json('{"title":"Set up the delivery checklist","body":"Read the agreed funding conditions. Record milestones, eligible spending instructions, receipts, who can approve changes and how to ask for a variation. Start the evidence folder before spending.","captureNotes":"Capture a fictional budget and milestone register with no real invoices or banking details. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A supplier price moves above a budget line before purchase. What do you check?","choices":[{"id":"a","text":"The relevant funding condition, authorised response and variation process if required."},{"id":"b","text":"Add it to a different line because the total grant is unchanged."},{"id":"c","text":"Wait to compare it during final reporting after paying."}],"correct_choice_id":"a","explanation":"Spending and changes need to be approved under the actual terms.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A volunteer report is proposed as outcome evidence. What makes it useful?","choices":[{"id":"a","text":"It is long and contains everyone''s private contact details."},{"id":"b","text":"It describes the relevant output, date and evidence handling agreed for the report."},{"id":"c","text":"It repeats the grant request so the reviewer can recognise the project."}],"correct_choice_id":"b","explanation":"The report needs relevant evidence that can be shared appropriately.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Prepare the close-out","body":"Compare approved and actual costs, report what changed and collect acceptable evidence of the outcome. Keep the reporting deadline, approval steps and outstanding issues visible to the next officer.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An approved variation moved a milestone. What do you report?","choices":[{"id":"a","text":"Only the new date with no reference to the agreement."},{"id":"b","text":"Only the original date and omit the reasons for differences."},{"id":"c","text":"The original and revised milestone, evidence of approval and what was actually delivered."}],"correct_choice_id":"c","explanation":"A complete evidence trail explains the change and its result.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A major cost changes during delivery. What should you check first?","choices":[{"id":"a","text":"Only the total funds remaining"},{"id":"b","text":"The funding agreement and the authorised change process"}],"correct_choice_id":"b","explanation":"A change can affect which costs or activities are authorised.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Translate the agreement into an operating checklist","body":"Read the confirmed agreement, eligible scope, budget, dates, milestones, procurement and variation rules, communications requirements, records and reports. Assign an accountable owner, authority and approval path to each. Agree how to record evidence and funding conditions before the project spends, and identify when a proposed variation is needed.\n\nKeep the source condition, decision, approved costs and owners with dates in the authorised record.","captureNotes":"Walk through Grants and project support with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the source condition, decision, approved costs and owners with dates using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The project was funded and a team wants to start a related activity outside the agreement. What first?","choices":[{"id":"a","text":"Use grant funds because the new activity supports the same broader purpose."},{"id":"b","text":"Check the funded scope and seek any required written approval or keep the activity separate."}],"correct_choice_id":"b","explanation":"The operating record needs the source condition, decision, approved costs and owners with dates. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the source condition, decision, approved costs and owners with dates"},{"id":"b","text":"a broad project plan with no reference to agreement conditions"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Track expenses, custody and evidence","body":"Use the correct budget line and approval for each spend. Keep quotes or invoices, approvals, receipts, dates, relevant equipment custody and who verified them. Explain in-kind or pending contributions separately from cash. Keep protected details out of general reports and document the responsible approvals and any variance.\n\nKeep the approved transaction, evidence, actual costs and exception owner in the authorised record.","captureNotes":"Walk through Expenditure register and evidence folder with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the approved transaction, evidence, actual costs and exception owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A receipt has no evidence it is for the approved activity. What should happen?","choices":[{"id":"a","text":"Flag it and confirm the purpose and approval before treating the spend as eligible."},{"id":"b","text":"File it under the category with the most unused budget."}],"correct_choice_id":"a","explanation":"The operating record needs the approved transaction, evidence, actual costs and exception owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a set of receipts without budget or approval links"},{"id":"b","text":"the approved transaction, evidence, actual costs and exception owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Manage variations, delays and risks","body":"Compare actual schedule, funding and outcomes against the agreement. Notify the authorised officer of a gap early and check the actual process for changing dates, scope or cost. Obtain any required written approval before spending or committing. Record what was accepted and update the plan, evidence and reports.\n\nKeep the original and revised terms, approval evidence and affected milestones in the authorised record.","captureNotes":"Walk through Project commitments and review with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the original and revised terms, approval evidence and affected milestones using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A milestone will be late and a revised date was agreed internally. What goes into the project file?","choices":[{"id":"a","text":"Replace the date in the internal schedule and treat the funder as notified."},{"id":"b","text":"The actual delay and any funder-required variation or advice, with the authorised decision and follow-up."}],"correct_choice_id":"b","explanation":"The operating record needs the original and revised terms, approval evidence and affected milestones. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the original and revised terms, approval evidence and affected milestones"},{"id":"b","text":"an edited schedule with no source or change history"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Close, acquit and preserve records","body":"Reconcile actual against approved costs and collect the evidence relevant to output and outcomes. Identify changes or unspent funds and follow the agreement. Have the right person verify the report, lodge through the named route and retain receipts or confirmation and required evidence through the agreed period. Handover open correspondence and checks to the operator or next officer.\n\nKeep the verified acquittal, approval and lodgement or follow-up, and retention owner in the authorised record.","captureNotes":"Walk through Delivery and grant reporting with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the verified acquittal, approval and lodgement or follow-up, and retention owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A final report is drafted before a missing invoice and venue approval have been verified. What is responsible?","choices":[{"id":"a","text":"Flag the gaps, get the appropriate checks or advice and accurately disclose any issue before authorised lodgement."},{"id":"b","text":"Submit the report as fully closed because the event was delivered."}],"correct_choice_id":"a","explanation":"The operating record needs the verified acquittal, approval and lodgement or follow-up, and retention owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"an event announcement and unchecked actuals"},{"id":"b","text":"the verified acquittal, approval and lodgement or follow-up, and retention owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Use a fictional funding agreement and expenditure register. Provide a dated delivery checklist, receipt and variance checks, a proposed or approved variation, budget versus actual outcomes evidence, approval and lodgement or reporting plan. Pass when every claimed cost and outcome traces to evidence, any unresolved condition is identified and the handover identifies who checks it next.',
  edit_version=edit_version+1
WHERE course_id='training-grant-delivery' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Turn a local idea into a clear need, workable budget and evidence checklist.',
  lessons_json=json_array(
    json('{"title":"Read the current programme guide","body":"Confirm the applicant, intent, eligibility, deadline and evidence with the official round material. Describe who benefits and what local evidence supports the need. Record what you still need to verify.","captureNotes":"Show the Ready SETCO Grants page and a fictional grant outline. Confirm any external round details at recording time. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two grant rounds have similar names. What do you verify first?","choices":[{"id":"a","text":"Find the round with the biggest budget and reuse last year''s eligibility notes."},{"id":"b","text":"Use a current announcement to assume the detailed conditions are identical."},{"id":"c","text":"The official guide for the actual round covering applicant, activity, dates and evidence."}],"correct_choice_id":"c","explanation":"The actual round document gives the terms a proposal needs to meet.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"The draft says many residents need a service but gives no evidence. What should you add?","choices":[{"id":"a","text":"A relevant local source or participation evidence showing who needs it and why."},{"id":"b","text":"A broader regional estimate without explaining its relation to the area."},{"id":"c","text":"An extra paragraph repeating the same claim in stronger words."}],"correct_choice_id":"a","explanation":"A reviewer needs to connect the claimed need to evidence.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Write the plan that could be delivered","body":"Connect activities, dates, costs and outcomes. Separate confirmed contributions from proposals and attach evidence of quotes or approval where the programme needs it. Have someone review the draft against the criteria.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"One activity cost is estimated and another is quoted. What goes in the budget?","choices":[{"id":"a","text":"Both as confirmed costs because a total is already needed."},{"id":"b","text":"Both as separate lines with their evidence status and a check for the estimate."},{"id":"c","text":"Only the quoted line and an unexplained buffer in the total."}],"correct_choice_id":"b","explanation":"Clear status makes the budget reviewable and the uncertainty visible.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An unconfirmed sponsorship is included in the budget. How should it appear?","choices":[{"id":"a","text":"As proposed with an owner to confirm it"},{"id":"b","text":"As committed income"}],"correct_choice_id":"a","explanation":"Budget reviewers need the funding status to judge whether the plan is viable.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Confirm the applicant and round","body":"Read the current official round documents. Confirm who can apply and sign, who benefits, intended area, eligibility, deadline, budget conditions and supporting approvals. If a partner or auspicing organisation is proposed, check consent and actual authority. Record source date, unresolved eligibility and the next decision.\n\nKeep the current round reference, dates, eligible applicant and outstanding permissions in the authorised record.","captureNotes":"Walk through Grants and project support with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the current round reference, dates, eligible applicant and outstanding permissions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An online guide describes a previous round and the new listing uses the same name. What do you do?","choices":[{"id":"a","text":"Verify the actual current round’s full terms before relying on the older guide."},{"id":"b","text":"Submit using past criteria and correct the application if asked."}],"correct_choice_id":"a","explanation":"The operating record needs the current round reference, dates, eligible applicant and outstanding permissions. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"last year’s successful example and a calendar reminder"},{"id":"b","text":"the current round reference, dates, eligible applicant and outstanding permissions"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Define need, scope, outcomes and delivery","body":"Give concrete local evidence of need, the intended participants and benefit, what can realistically be provided and how it will be measured. Confirm partners, site and personnel requirements. Make the activity and timeline match actual capacity and approvals and describe the key risks and alternatives. Identify who will deliver, measure and review.\n\nKeep the evidence-backed need, work plan, outcome measure and named responsibilities in the authorised record.","captureNotes":"Walk through Project outline and evaluation with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the evidence-backed need, work plan, outcome measure and named responsibilities using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The proposal promises participation but has no evidence that people want the service. What is a responsible change?","choices":[{"id":"a","text":"Use a larger unsupported estimate to make the programme seem worthwhile."},{"id":"b","text":"Gather relevant evidence or state the gap, with a workable target and way to test it."}],"correct_choice_id":"b","explanation":"The operating record needs the evidence-backed need, work plan, outcome measure and named responsibilities. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the evidence-backed need, work plan, outcome measure and named responsibilities"},{"id":"b","text":"repeated claims of demand with no source"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Build a transparent budget and evidence pack","body":"Use quantities and quoted or clearly dated estimated costs. Record price evidence, eligible and ineligible expenses, funding status and who can confirm each contribution. Include relevant insurance, site costs, maintenance and reporting where applicable. Check for double-counted income or restricted funds. Keep supporting documents and permissions with their versions and owners.\n\nKeep the cost evidence, conditional resources, budget basis and actual approvals in the authorised record.","captureNotes":"Walk through Budget, quotations and decision register with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the cost evidence, conditional resources, budget basis and actual approvals using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A sponsor and a volunteer both offer the same gear. How should it appear?","choices":[{"id":"a","text":"Check the intended option, mark both offers and avoid counting either twice or as confirmed prematurely."},{"id":"b","text":"Add both contributions as confirmed resources since either might be used."}],"correct_choice_id":"a","explanation":"The operating record needs the cost evidence, conditional resources, budget basis and actual approvals. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a total budget without a breakdown or source"},{"id":"b","text":"the cost evidence, conditional resources, budget basis and actual approvals"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Review, submit and hand over the application","body":"Have the right people compare the draft against every criterion and verify approvals, claims, figures, documents and audience. Confirm the final version and authorised signatory before lodgement and save the actual receipt. Give the next person current status, decisions, deadlines and what would have to change if funding is declined or awarded with conditions.\n\nKeep the lodged version, authority, receipt and who checks decisions or conditions in the authorised record.","captureNotes":"Walk through Grant application and closing checklist with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the lodged version, authority, receipt and who checks decisions or conditions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The draft is complete but the approved signatory and delivery evidence are unconfirmed. What is the next step?","choices":[{"id":"a","text":"Submit and assume the email acknowledgement confirms all the missing information."},{"id":"b","text":"Keep it pending, resolve both checks and record the authorised final submission."}],"correct_choice_id":"b","explanation":"The operating record needs the lodged version, authority, receipt and who checks decisions or conditions. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the lodged version, authority, receipt and who checks decisions or conditions"},{"id":"b","text":"a draft PDF and no record of actual lodgement"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Develop a fictional grant application extract with a dated official criteria check, applicant and signatory, sourced need, delivery plan, measurable outcome, budget with quotes or assumptions, and permission and submission checks. Include one held or conditional contribution. Pass when the proposal can be reviewed against each condition and costs, roles and factual claims have an evidence trail.',
  edit_version=edit_version+1
WHERE course_id='training-grant-writing' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Prepare a short work profile and ask useful questions before taking on a local job.',
  lessons_json=json_array(
    json('{"title":"Describe what you can do","body":"List relevant tasks, experience and availability. Pick one example that shows your skill. Keep identity documents and contact details out of public posts. Offer any evidence through the agreed private review process.","captureNotes":"Use a fictional Learning & work profile in an authorised test account. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Which work profile statement gives an employer something useful to discuss?","choices":[{"id":"a","text":"A broad claim to be available for any role, without an example."},{"id":"b","text":"A specific skill example, actual availability and a question about the role."},{"id":"c","text":"A list of identity document numbers to prove readiness publicly."}],"correct_choice_id":"b","explanation":"Relevant examples and availability help a conversation without exposing private evidence.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A role asks for a licence check. What should you share first in the public enquiry?","choices":[{"id":"a","text":"A full scan and its number so the employer can check it later."},{"id":"b","text":"The same document to every business linked to the project."},{"id":"c","text":"The relevant licence type and ask how the authorised check is handled."}],"correct_choice_id":"c","explanation":"Verification can be arranged privately and scoped to the actual role.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Clarify a role before saying yes","body":"Ask who the employer is, what work is required, where and when it happens, who supervises and what training or checks apply. Ask how pay and work arrangements will be confirmed.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two organisations are named on a job idea, and neither is identified as the employer. What do you ask?","choices":[{"id":"a","text":"Who actually employs and supervises, what terms apply and how they are agreed."},{"id":"b","text":"Which one designed the form because that company must be the employer."},{"id":"c","text":"Which one is the largest and whether it can send a general pay schedule."}],"correct_choice_id":"a","explanation":"The actual employer and supervisor need to be clear.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which detail should be clear before agreeing to a role?","choices":[{"id":"a","text":"The actual employer, duties, arrangements and supervisor"},{"id":"b","text":"Only the name of a project"}],"correct_choice_id":"a","explanation":"The actual role determines what you and the employer need to agree.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Verify employer, job and agreed conditions","body":"Ask who employs and supervises, where and when duties take place, the nature of the arrangement, pay and how changes or cancellation work. Check licences, skills, training, equipment and accessibility needs against the actual role. Use current Fair Work guidance and a qualified source as needed. Keep the offer and confirmed terms distinct.\n\nKeep the confirmed job and responsible employer, terms and open verification in the authorised record.","captureNotes":"Walk through Training and work with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the confirmed job and responsible employer, terms and open verification using invented details. Check current pay, responsibilities and records with Fair Work and the role’s authorised supervisor.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A project suggests shifts but cannot say who the employer is. What should happen before you accept?","choices":[{"id":"a","text":"Start for the project and ask which business will pay after the first shift."},{"id":"b","text":"Confirm the actual employer, supervisor, duties, terms and records."}],"correct_choice_id":"b","explanation":"The operating record needs the confirmed job and responsible employer, terms and open verification. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the confirmed job and responsible employer, terms and open verification"},{"id":"b","text":"an advertised opportunity and an estimated rate only"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Arrange skills or work-rights checks privately","body":"Prepare an example of the relevant work, licence type or training history without sharing document numbers publicly. Ask what the employer needs to verify and how through the authorised route. Separate what you describe from an actual check. Agree who can see any record and confirm which duties remain dependent on the result.\n\nKeep the scoped check, responsible recipient and agreed records in the authorised record.","captureNotes":"Walk through Learning and work profile and authorised employer process with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the scoped check, responsible recipient and agreed records using invented details. Check current pay, responsibilities and records with Fair Work and the role’s authorised supervisor.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A notice asks for a passport and licence photograph in a public comment. What do you do?","choices":[{"id":"a","text":"Ask for the authorised private process for only the checks the role requires."},{"id":"b","text":"Post the documents and delete the comment after the employer responds."}],"correct_choice_id":"a","explanation":"The operating record needs the scoped check, responsible recipient and agreed records. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a public attachment with unneeded identifying data"},{"id":"b","text":"the scoped check, responsible recipient and agreed records"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Prepare for induction and handle a changed shift","body":"Confirm arrival, duty, equipment, training, pay record, roster and supervisor. Ask how a safety issue, additional duty or concern is raised and who decides a change. Keep appropriate working time and pay evidence and check it with the employer. Ask the authorised or official advice route if a disagreement stays unresolved.\n\nKeep the actual shift, change and authoriser, and where the related record is kept in the authorised record.","captureNotes":"Walk through Employer induction and contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the actual shift, change and authoriser, and where the related record is kept using invented details. Check current pay, responsibilities and records with Fair Work and the role’s authorised supervisor.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The site lead adds duties and hours that differ from the confirmed roster. What is useful first?","choices":[{"id":"a","text":"Work the new hours and rely on the advertised rates without confirming."},{"id":"b","text":"Clarify the authorised change, responsibilities, record and pay with the supervisor or employer."}],"correct_choice_id":"b","explanation":"The operating record needs the actual shift, change and authoriser, and where the related record is kept. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the actual shift, change and authoriser, and where the related record is kept"},{"id":"b","text":"a roster screenshot with no record of actual changes"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Follow through and preserve work evidence","body":"At the end of a shift or role, confirm clearly how time and pay were recorded and hand over gear, work or issues to the named person. Keep your authorised agreements, receipts or payslips and a private record of questions. Check before sharing a reference or work output and agree who can verify your experience for a future role.\n\nKeep your agreed terms, actual records, discrepancies and follow-up contact in the authorised record.","captureNotes":"Walk through Employment records and supervisor with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include your agreed terms, actual records, discrepancies and follow-up contact using invented details. Check current pay, responsibilities and records with Fair Work and the role’s authorised supervisor.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A payslip or work record does not match your hours. How should it be followed up?","choices":[{"id":"a","text":"Compare the evidence and raise it through the authorised employer or official advice process."},{"id":"b","text":"Discard your record and accept the employer’s total because it was issued formally."}],"correct_choice_id":"a","explanation":"The operating record needs your agreed terms, actual records, discrepancies and follow-up contact. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a self-written total without supporting shift or pay evidence"},{"id":"b","text":"your agreed terms, actual records, discrepancies and follow-up contact"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Prepare a fictional local job pack with a relevant skills example, employer and supervisor check, duties, hours and pay or terms to confirm, and a scoped private licence or credential check. Handle a changed shift and one mismatched pay or work record. Pass when the next contact, agreed terms and what still needs verification can be identified without exposing personal documents.',
  edit_version=edit_version+1
WHERE course_id='training-local-work' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Explore the public lessons, local project pages, private portal and ways to take part.',
  lessons_json=json_array(
    json('{"title":"Start with a public page","body":"From the homepage, open Take part and try the sample volunteer lesson. Explore Training & work, the community map and the proposed cooperative formation pages for routes that suit you.","captureNotes":"Capture the public home and sample lesson. Use the public pages in the recording. Reference site: https://ready-setco.auraofintelligence.workers.dev/"}'),
    json('{"title":"Choose the next step","body":"Send an enquiry if you want a private follow-up. Use your own portal account when you need to access a group, see assigned courses or keep a private participation record. Ask the organiser which process applies to your goal."}'),
    json('{"title":"Explore the project through useful pages","body":"Use Home for the proposal, Training & work for skills and employment, Map for public places, and Co-op hub for rules or participation. Check the status of proposed projects, activities and agreements through their responsible contact before relying on them.","captureNotes":"Walk through Home, Training & work and Co-op hub with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}'),
    json('{"title":"Choose the right public or private route","body":"Try the public lesson or send a private enquiry to discuss a next step. Use your own account when you are arranging authorised access, learning or participation. Ask what use is intended before sharing sensitive documents or participant details.","captureNotes":"Walk through Take part and Member portal with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}'),
    json('{"title":"Get help and verify changes","body":"Ask event or project owners for confirmed arrangements, use the map correction process when a public place is wrong and use the portal’s appropriate private support for access or profile issues. Check related projects’ own sources if you want to verify what they do.","captureNotes":"Walk through Public contact, map or portal with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='training-site-tour' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Choose a task, meet the shift lead and leave the next person a useful handover.',
  lessons_json=json_array(
    json('{"title":"Confirm the shift","body":"Ask where and when to check in, what work has been agreed, what training or gear you need and who makes a change-of-plan decision. Raise access needs with the lead.","captureNotes":"Use a fictional event run sheet and show a sample shift briefing. Reference site: https://ready-setco.auraofintelligence.workers.dev/"}'),
    json('{"title":"Close out your work","body":"Return the agreed equipment, tell the lead what was done and hand over unfinished actions. Ask how concerns and incidents are recorded. If the project is trialling voluntary contribution records, agree who could verify the time."}'),
    json('{"title":"Match your offer to an agreed job","body":"Ask for the exact role, when to check in, who supervises, where instructions live, training, expenses and which work belongs to another role. Confirm whether any safety or screening checks apply and who confirms them before you take responsibility.","captureNotes":"Walk through Take part and shift lead with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}'),
    json('{"title":"Support visitors and respond to concerns","body":"Know who can change the plan, how to check a public update and what to do if equipment or conditions change. Stay within what was agreed and contact the responsible lead about welfare, safeguarding or access. Use the agreed emergency procedure for urgent concerns.","captureNotes":"Walk through Event briefing and private referral with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}'),
    json('{"title":"Close your shift and record a contribution","body":"Return equipment and agree custody or follow-up, report issues and tell the next person what remains. Discuss how to verify any voluntary contribution record and how to give feedback without putting private information on a shared channel.","captureNotes":"Walk through Volunteer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='training-volunteer' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find the official sources, keep useful work records and ask what a role involves.',
  lessons_json=json_array(
    json('{"title":"Check the current rules for your situation","body":"Use the relevant Home Affairs pages and the official work-rights process where applicable. Match the actual job, location and dates to the current guidance for your situation. Keep the source and date of your check.","captureNotes":"Show the site’s working-holiday pathway and where to find current official pages. Use fictional records and avoid displaying personal documents. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An old example and a current official page give different conditions. Which do you use?","choices":[{"id":"a","text":"Use the older example if it matches your plans more closely."},{"id":"b","text":"Apply the same rule to all workers on working holidays."},{"id":"c","text":"Use the current official guidance for your actual visa and job, and date the check."}],"correct_choice_id":"c","explanation":"Conditions depend on current guidance and the person''s actual situation.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A town is listed on a promotional page but the employer proposes shifts elsewhere. What should be checked?","choices":[{"id":"a","text":"The actual work location and duties against the relevant current guidance."},{"id":"b","text":"The business''s registered address only."},{"id":"c","text":"The promotional listing as proof for every shift."}],"correct_choice_id":"a","explanation":"It is the actual work and location that need checking.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Prepare records and ask before you start","body":"Ask the employer about the actual tasks, location, pay and records they provide. Agree how to keep payslips, contracts and work dates. Treat community volunteering as a separate activity and check any claim about specified work with the official source.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An employer says records will be supplied later and asks you to start now. What should you clarify?","choices":[{"id":"a","text":"Only whether the employer has hired working holiday workers before."},{"id":"b","text":"The role and pay terms, and which dates and evidence they will record and provide."},{"id":"c","text":"Whether the volunteer team can write one confirmation for all kinds of work."}],"correct_choice_id":"b","explanation":"Work agreements and records need to match the actual arrangement.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A job listing claims it will count. What should you do?","choices":[{"id":"a","text":"Rely on the listing’s claim by itself"},{"id":"b","text":"Check the current official rules against the actual role and location"}],"correct_choice_id":"b","explanation":"The relevant official conditions and actual work matter.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Verify current subclass, conditions and actual job","body":"Check your grant and official Home Affairs guidance for the actual visa subclass, conditions and changes that apply to your dates. Confirm tasks, employer, place and working arrangements. Treat the employer’s advertised claims as a prompt to verify against the relevant official work guidance. Keep the source and date checked and seek authorised advice for unresolved cases.\n\nKeep the actual role, dated source checks and any question still needing official advice in the authorised record.","captureNotes":"Walk through Working holiday pathway and Home Affairs with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the actual role, dated source checks and any question still needing official advice using invented details. Check current Home Affairs subclass and role requirements using its Working Holiday Maker pages and current Fair Work guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A listing says all jobs at the advertised town qualify, but duties vary. What should you check?","choices":[{"id":"a","text":"Actual duties, location, conditions and relevant rule for your subclass and dates with the official source."},{"id":"b","text":"The business postcode and advertisement as proof of every shift."}],"correct_choice_id":"a","explanation":"The operating record needs the actual role, dated source checks and any question still needing official advice. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a screenshot of a job ad promising eligibility"},{"id":"b","text":"the actual role, dated source checks and any question still needing official advice"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Distinguish permitted work, specified work and volunteering","body":"Check current evidence of permission to work and, separately, whether a particular job may count for a later application. Check workplace terms and pay using official Fair Work guidance or support. Keep an offer to volunteer separate and ask about its actual duties, terms, contacts and records. Avoid accepting an assurance of visa outcomes from an advert or informal intermediary.\n\nKeep separate dated records for actual employment terms, official checks and any volunteer arrangement in the authorised record.","captureNotes":"Walk through Home Affairs and Fair Work sources with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include separate dated records for actual employment terms, official checks and any volunteer arrangement using invented details. Check current Home Affairs subclass and role requirements using its Working Holiday Maker pages and current Fair Work guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A host offers a volunteer shift and says it will count as specified work. What should you do?","choices":[{"id":"a","text":"Count the shift because the host can sign a record of attendance."},{"id":"b","text":"Check official visa rules and actual arrangements separately before relying on the claim."}],"correct_choice_id":"b","explanation":"The operating record needs separate dated records for actual employment terms, official checks and any volunteer arrangement. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"separate dated records for actual employment terms, official checks and any volunteer arrangement"},{"id":"b","text":"one hours total combining every type of work"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Handle job, location or employer changes","body":"Before accepting a changed job, employer, workplace or duties, recheck the relevant conditions and the actual arrangement. Record who proposed the change, date and supporting evidence. Resolve uncertainty through official or authorised advice before relying on it. Use the employer’s verified private method if a work-rights check is needed and keep unnecessary details out of the profile.\n\nKeep the actual changes, source checks, dates and separate evidence for each arrangement in the authorised record.","captureNotes":"Walk through Employment agreement and records with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the actual changes, source checks, dates and separate evidence for each arrangement using invented details. Check current Home Affairs subclass and role requirements using its Working Holiday Maker pages and current Fair Work guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"You are moved to a different job site for the rest of the month. What changes in your checks?","choices":[{"id":"a","text":"Verify the new actual location, duties and relevant conditions and record the change from when it applies."},{"id":"b","text":"Keep using the original site on every record because the employer is the same."}],"correct_choice_id":"a","explanation":"The operating record needs the actual changes, source checks, dates and separate evidence for each arrangement. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the old job description copied through the whole period"},{"id":"b","text":"the actual changes, source checks, dates and separate evidence for each arrangement"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Keep proof and know where to raise a concern","body":"Keep a dated, private evidence file for the role, location and terms, actual work pattern, contact, payslips and other official evidence relevant to your circumstances. Check what the current application process accepts. Compare records as they arrive and raise missing, inaccurate or unpaid work through the appropriate route. Ask official or authorised advice where your circumstances are uncertain.\n\nKeep the actual evidence and missing items, dated sources and responsible follow-up in the authorised record.","captureNotes":"Walk through Official work and employment records with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://ready-setco.auraofintelligence.workers.dev/ Include the actual evidence and missing items, dated sources and responsible follow-up using invented details. Check current Home Affairs subclass and role requirements using its Working Holiday Maker pages and current Fair Work guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The employer offers a later letter but no contemporaneous records of shifts or pay. What is sensible?","choices":[{"id":"a","text":"Use the promise as proof and wait until a visa application is due."},{"id":"b","text":"Confirm what evidence the official process expects and seek actual records and appropriate advice now."}],"correct_choice_id":"b","explanation":"The operating record needs the actual evidence and missing items, dated sources and responsible follow-up. This lets the next person verify the work and any remaining decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the actual evidence and missing items, dated sources and responsible follow-up"},{"id":"b","text":"an employer’s verbal promise without supporting work records"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Using a fictional job offer, create a scoped check for actual employer, duties, location and conditions, with dated sources for work rights and any claimed specified work. Set out terms, work evidence to keep, a changed site or duty and an unresolved pay or eligibility question to refer. Pass when the different checks are separated, sources match the example and the evidence and follow-up can be reproduced without personal documents.',
  edit_version=edit_version+1
